<#
.SYNOPSIS
    QLDATN Project Tracker - Bo Cai Dat Cho Visual Studio Code (PowerShell)
.DESCRIPTION
    Tu dong cau hinh workspace VS Code va cai dat extension QLDATN Tracker
    chay truc tiep tren Windows ma khong can cai dat Node.js.
    Chay script nay trong thu muc goc cua du an:
        powershell -ExecutionPolicy Bypass -File <ten-file>.ps1
#>

[System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor [System.Net.SecurityProtocolType]::Tls12
$OutputEncoding = [System.Text.Encoding]::UTF8
if ([Console]::OutputEncoding) {
    try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}
}

$ErrorActionPreference = "Stop"
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

Write-Host "[QLDATN] Dang khoi tao bo cai dat Tracker cho VS Code..." -ForegroundColor Cyan

# 1. Tu dong them file bo cai vao .gitignore
$root = if ($PSScriptRoot) { $PSScriptRoot } else { Get-Location }
$gitignorePath = Join-Path $root ".gitignore"
$ignoreRules = @("qldatn-vscode-install_*.ps1", "qldatn-vscode-install_*.mjs")
if (Test-Path $gitignorePath) {
    $currentIgnore = Get-Content -Path $gitignorePath -Raw -Encoding UTF8
    $lines = $currentIgnore -split '\r?\n'
    $missing = $ignoreRules | Where-Object { $lines -notcontains $_ }
    if ($missing.Count -gt 0) {
        Add-Content -Path $gitignorePath -Value ($missing -join [Environment]::NewLine) -Encoding UTF8
        Write-Host "[QLDATN] Da tu dong them file bo cai dat vao .gitignore" -ForegroundColor Yellow
    }
}

# 2. Tao thu muc .vscode va cau hinh settings.json
$vscodeDir = Join-Path $root ".vscode"
if (!(Test-Path $vscodeDir)) {
    New-Item -ItemType Directory -Path $vscodeDir -Force | Out-Null
}

$settingsPath = Join-Path $vscodeDir "settings.json"
$settings = @{}
if (Test-Path $settingsPath) {
    try {
        $rawSettings = Get-Content -Path $settingsPath -Raw -Encoding UTF8
        $cleanSettings = $rawSettings -replace '(?m)^\s*//.*$', '' -replace '/\*[\s\S]*?\*/', ''
        if ($cleanSettings.Trim().Length -gt 0) {
            $parsed = ConvertFrom-Json $cleanSettings
            if ($parsed) {
                foreach ($prop in $parsed.PSObject.Properties) {
                    $settings[$prop.Name] = $prop.Value
                }
            }
        }
    } catch {}
}

$settings["qldatn.trackerUrl"] = "https://datn.unifolio.io.vn"
$settings["qldatn.enrollmentCode"] = "qlde_Q_KgBnjmmkvpGSqTu9ALdOafAOrAyykUl3fe1Ff1Niw"
$settings["qldatn.heartbeatIntervalSeconds"] = 30
$settings["qldatn.idleTimeoutMinutes"] = 3

$settingsJson = ConvertTo-Json $settings -Depth 10
[System.IO.File]::WriteAllText($settingsPath, $settingsJson + [Environment]::NewLine, $utf8NoBom)

# 3. Them khuyen nghi extension trong extensions.json
$extensionsPath = Join-Path $vscodeDir "extensions.json"
$recommendations = @("qldatn.qldatn-tracker")
if (Test-Path $extensionsPath) {
    try {
        $rawExt = Get-Content -Path $extensionsPath -Raw -Encoding UTF8
        $cleanExt = $rawExt -replace '(?m)^\s*//.*$', '' -replace '/\*[\s\S]*?\*/', ''
        if ($cleanExt.Trim().Length -gt 0) {
            $extObj = ConvertFrom-Json $cleanExt
            if ($extObj.recommendations) {
                foreach ($rec in $extObj.recommendations) {
                    if ($rec -ne "fpoly-qldatn.qldatn-tracker" -and $recommendations -notcontains $rec) {
                        $recommendations += $rec
                    }
                }
            }
        }
    } catch {}
}
$extJson = ConvertTo-Json @{ recommendations = $recommendations } -Depth 5
[System.IO.File]::WriteAllText($extensionsPath, $extJson + [Environment]::NewLine, $utf8NoBom)

# 4. Cai dat extension vao thu muc extensions cua VS Code
$manifest = @'
{
  "name": "qldatn-tracker",
  "displayName": "QLDATN Project Tracker",
  "description": "Theo doi tien do phat trien du an tot nghiep tu dong cho VS Code (QLDATN)",
  "version": "1.0.0",
  "publisher": "qldatn",
  "engines": { "vscode": "^1.65.0" },
  "main": "./extension.js",
  "activationEvents": ["onStartupFinished"],
  "contributes": {
    "commands": [
      { "command": "qldatn.enroll", "title": "QLDATN: Kich hoat / Lien ket ma theo doi", "category": "QLDATN" },
      { "command": "qldatn.status", "title": "QLDATN: Kiem tra trang thai Tracker", "category": "QLDATN" },
      { "command": "qldatn.toggle", "title": "QLDATN: Bat / Tat tam thoi ghi nhan", "category": "QLDATN" },
      { "command": "qldatn.sync", "title": "QLDATN: Dong bo tien do ngay lap tuc", "category": "QLDATN" },
      { "command": "qldatn.openDashboard", "title": "QLDATN: Mo trang tong quan du an", "category": "QLDATN" }
    ],
    "keybindings": [
      { "command": "qldatn.sync", "key": "alt+shift+s", "mac": "cmd+alt+s" },
      { "command": "qldatn.openDashboard", "key": "alt+shift+d", "mac": "cmd+alt+d" }
    ],
    "configuration": {
      "title": "QLDATN Project Tracker",
      "properties": {
        "qldatn.trackerUrl": { "type": "string", "default": "", "description": "URL may chu QLDATN" },
        "qldatn.enrollmentCode": { "type": "string", "default": "", "description": "Ma kich hoat dang ky thiet bi" },
        "qldatn.idleTimeoutMinutes": { "type": "number", "default": 3, "description": "Thoi gian phat hien treo may (Anti-AFK)" },
        "qldatn.heartbeatIntervalSeconds": { "type": "number", "default": 30, "description": "Chu ky gui tin hieu theo doi (giay)" }
      }
    }
  }
}
'@

$artifactUrl = "https://datn.unifolio.io.vn/api/project-tracker/client-artifact?platform=VS_CODE"
$vsixBase64 = ""
$extJsBase64 = ""
$pkgJsonBase64 = ""

$cliInstalled = $false

# 4.1. Thu cai dat bang CLI (code --install-extension) neu he thong co san CLI
$cliCandidates = @(
    "code",
    "cursor",
    "windsurf",
    "code-insiders"
)
if ($env:LOCALAPPDATA) {
    $cliCandidates += (Join-Path $env:LOCALAPPDATA "Programs\Microsoft VS Code\bin\code.cmd")
    $cliCandidates += (Join-Path $env:LOCALAPPDATA "Programs\cursor\resources\app\bin\cursor.cmd")
    $cliCandidates += (Join-Path $env:LOCALAPPDATA "Programs\Windsurf\bin\windsurf.cmd")
}
if ($env:ProgramFiles) {
    $cliCandidates += (Join-Path $env:ProgramFiles "Microsoft VS Code\bin\code.cmd")
}
if (${env:ProgramFiles(x86)}) {
    $cliCandidates += (Join-Path ${env:ProgramFiles(x86)} "Microsoft VS Code\bin\code.cmd")
}

$tempVsix = Join-Path ([System.IO.Path]::GetTempPath()) "qldatn-tracker-1.0.0.vsix"
try {
    if ($vsixBase64.Length -gt 0) {
        $vsixBytes = [System.Convert]::FromBase64String($vsixBase64)
        [System.IO.File]::WriteAllBytes($tempVsix, $vsixBytes)
        foreach ($cli in $cliCandidates) {
            $cmdObj = Get-Command $cli -ErrorAction SilentlyContinue
            $cliPath = if ($cmdObj) { $cmdObj.Source } elseif (Test-Path $cli) { $cli } else { $null }
            if ($cliPath) {
                try {
                    $process = Start-Process -FilePath $cliPath -ArgumentList @("--install-extension", $tempVsix, "--force") -NoNewWindow -Wait -PassThru -ErrorAction SilentlyContinue
                    if ($process -and $process.ExitCode -eq 0) {
                        $cliInstalled = $true
                    }
                } catch {}
            }
        }
    }
} catch {} finally {
    if (Test-Path $tempVsix) {
        Remove-Item -Path $tempVsix -Force -ErrorAction SilentlyContinue
    }
}

# 4.2. Giai nen / sao chep truc tiep vao thu muc extensions
$targetHomes = @()
$primaryHome = [Environment]::GetFolderPath("UserProfile")
if (!$primaryHome) { $primaryHome = $env:USERPROFILE }
if (!$primaryHome) { $primaryHome = $HOME }
if ($primaryHome -and (Test-Path $primaryHome)) { $targetHomes += $primaryHome }

try {
    $explorer = Get-CimInstance Win32_Process -Filter "name = 'explorer.exe'" -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($explorer) {
        $owner = Invoke-CimMethod -InputObject $explorer -MethodName GetOwner -ErrorAction SilentlyContinue
        if ($owner -and $owner.User) {
            $realHome = "C:\Users\" + $owner.User
            if ((Test-Path $realHome) -and ($targetHomes -notcontains $realHome)) {
                $targetHomes += $realHome
            }
        }
    }
} catch {}

try {
    if (Test-Path "C:\Users") {
        Get-ChildItem -Path "C:\Users" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $candHome = $_.FullName
            if ((Test-Path (Join-Path $candHome ".vscode")) -and ($targetHomes -notcontains $candHome)) {
                $targetHomes += $candHome
            }
        }
    }
} catch {}

$candidateDirs = @()
foreach ($h in $targetHomes) {
    $candidateDirs += (Join-Path $h ".vscode\extensions")
    $candidateDirs += (Join-Path $h ".vscode-insiders\extensions")
    $candidateDirs += (Join-Path $h ".cursor\extensions")
    $candidateDirs += (Join-Path $h ".windsurf\extensions")
    $candidateDirs += (Join-Path $h ".vscode-oss\extensions")
}

$targetDirs = @()
foreach ($cand in $candidateDirs) {
    $parent = Split-Path $cand -Parent
    if (Test-Path $parent) {
        if ($targetDirs -notcontains $cand) {
            $targetDirs += $cand
        }
    }
}
if ($targetDirs.Count -eq 0 -and $candidateDirs.Count -gt 0) {
    $targetDirs += $candidateDirs[0]
}

$extJsBytes = if ($extJsBase64.Length -gt 0) { [System.Convert]::FromBase64String($extJsBase64) } else { $null }
$pkgJsonBytes = if ($pkgJsonBase64.Length -gt 0) { [System.Convert]::FromBase64String($pkgJsonBase64) } else { $null }

# Fallback tai qua mang neu thieu ma nguon nhung
if (!$extJsBytes) {
    try {
        $wc = New-Object System.Net.WebClient
        $wc.Encoding = [System.Text.Encoding]::UTF8
        $wc.Headers.Add("User-Agent", "QLDATN-VSCode-Installer")
        $netSource = $wc.DownloadString($artifactUrl)
        if ($netSource) {
            $extJsBytes = [System.Text.Encoding]::UTF8.GetBytes($netSource)
        }
    } catch {
        try {
            $netSource = (Invoke-RestMethod -Uri $artifactUrl -UseBasicParsing -UserAgent "QLDATN-VSCode-Installer")
            if ($netSource) {
                $extJsBytes = [System.Text.Encoding]::UTF8.GetBytes($netSource)
            }
        } catch {}
    }
}

foreach ($userExtensionsDir in $targetDirs) {
    $oldExt = Join-Path $userExtensionsDir "fpoly-qldatn.qldatn-tracker-1.0.0"
    if (Test-Path $oldExt) {
        Remove-Item $oldExt -Recurse -Force -ErrorAction SilentlyContinue
    }

    $obsoletePath = Join-Path $userExtensionsDir ".obsolete"
    if (Test-Path $obsoletePath) {
        try {
            $rawObs = Get-Content -Path $obsoletePath -Raw -Encoding UTF8
            if ($rawObs -and $rawObs.Contains("qldatn")) {
                $obsObj = ConvertFrom-Json $rawObs
                $obsChanged = $false
                if ($obsObj) {
                    $props = @($obsObj.PSObject.Properties)
                    foreach ($p in $props) {
                        if ($p.Name -like "*qldatn*") {
                            $obsObj.PSObject.Properties.Remove($p.Name)
                            $obsChanged = $true
                        }
                    }
                }
                if ($obsChanged) {
                    $updatedObs = ConvertTo-Json $obsObj -Depth 5
                    [System.IO.File]::WriteAllText($obsoletePath, $updatedObs + [Environment]::NewLine, $utf8NoBom)
                }
            }
        } catch {}
    }

    $targetExt = Join-Path $userExtensionsDir "qldatn.qldatn-tracker-1.0.0"
    if (!(Test-Path $targetExt)) {
        New-Item -ItemType Directory -Path $targetExt -Force | Out-Null
    }

    if ($pkgJsonBytes) {
        [System.IO.File]::WriteAllBytes((Join-Path $targetExt "package.json"), $pkgJsonBytes)
    } else {
        [System.IO.File]::WriteAllText((Join-Path $targetExt "package.json"), $manifest, $utf8NoBom)
    }

    if ($extJsBytes) {
        [System.IO.File]::WriteAllBytes((Join-Path $targetExt "extension.js"), $extJsBytes)
    }
}

# 4.3. Kiem tra xac thuc tren dia (Verification Guard)
$verifiedCount = 0
foreach ($userExtensionsDir in $targetDirs) {
    $checkFile = Join-Path $userExtensionsDir "qldatn.qldatn-tracker-1.0.0\extension.js"
    if (Test-Path $checkFile -PathType Leaf) {
        $verifiedCount++
    }
}
$isSuccess = ($verifiedCount -gt 0) -or $cliInstalled

if (!$isSuccess) {
    Write-Host ""
    Write-Host "[QLDATN] LOI: Khong the cai dat Extension vao VS Code!" -ForegroundColor Red
    Write-Host "[QLDATN] Vui long kiem tra quyen ghi hoac tai file VSIX tu web de cai dat thu cong." -ForegroundColor Yellow
    Write-Host "[QLDATN] File script duoc giu nguyen de ban co the thu lai." -ForegroundColor Yellow
    Write-Host ""
    exit 1
}

Write-Host "[QLDATN] Da tu dong cai dat Extension vao Visual Studio Code!" -ForegroundColor Green
Write-Host ""
Write-Host "[QLDATN] Da cau hinh workspace VS Code thanh cong tai .vscode/settings.json!" -ForegroundColor Green
Write-Host "[QLDATN] Ma lien ket cua ban: qlde_Q_KgBnjmmkvpGSqTu9ALdOafAOrAyykUl3fe1Ff1Niw" -ForegroundColor Cyan

# 5. Kiem tra tien trinh VS Code dang chay
$runningCode = Get-Process -Name "Code" -ErrorAction SilentlyContinue
if ($runningCode) {
    Write-Host ""
    Write-Host "[QLDATN] LUU Y QUAN TRONG: Visual Studio Code dang chay!" -ForegroundColor Yellow
    Write-Host "[QLDATN] Hay khoi dong lai VS Code hoac nhan Ctrl+Shift+P va chon 'Developer: Reload Window' de VS Code tai Extension moi." -ForegroundColor Yellow
    Write-Host ""
} else {
    Write-Host "[QLDATN] Mo VS Code trong thu muc nay, extension QLDATN Tracker se tu dong kich hoat." -ForegroundColor White
}
Write-Host "[QLDATN] Tinh nang Anti-AFK (Phat hien treo may) da duoc bat mac dinh sau 3 phut khong thao tac." -ForegroundColor Cyan
Write-Host ""

# 6. Tu dong don dep file script cai dat chi khi da xac thuc thanh cong
try {
    $scriptPath = if ($MyInvocation.MyCommand.Path) { $MyInvocation.MyCommand.Path } elseif ($PSCommandPath) { $PSCommandPath } else { $null }
    if ($scriptPath -and (Test-Path $scriptPath)) {
        Remove-Item -Path $scriptPath -Force -ErrorAction SilentlyContinue
        Write-Host "[QLDATN] File cai dat dung mot lan da duoc tu dong don dep." -ForegroundColor Gray
    }
} catch {}
